mapper.update:
UPDATE cart
SET quantity = #{quantity}
WHERE username = #{username}
  AND product_id = #{productId};

UPDATE cart
SET quantity = quantity + 1
WHERE username = #{username}
  AND product_id = #{productId};

UPDATE cart
SET quantity = quantity - 1
WHERE username = #{username}
  AND product_id = #{productId}
  AND quantity > 1;

mapper.delete:
DELETE FROM cart
WHERE username = #{username}
  AND product_id = #{productId};
